from math import isqrt

def prod2sum(a, b, c, d):
    # Calculate the sums of squares of a and b, and c and d
    sum_ab = a**2 + b**2
    sum_cd = c**2 + d**2

    # Calculate the product of these sums
    n = sum_ab * sum_cd

    # Initialize a set to store unique pairs (e, f)
    pairs = set()

    # Generate all possible pairs (e, f) such that e = x*y and f = z*w
    # where x, y, z, w are chosen from {a, b, c, d} and are distinct
    for x in [a, b, c, d]:
        for y in [a, b, c, d]:
            if x != y:
                for z in [a, b, c, d]:
                    if z != x and z != y:
                        for w in [a, b, c, d]:
                            if w != x and w != y and w != z:
                                e = x * y
                                f = z * w
                                if e + f == n:
                                    pairs.add((min(e, f), max(e, f)))

    # Convert the set to a sorted list of tuples
    result = sorted(list(pairs))

    return result

