    pairs = set()

    # Iterate over all possible pairs (i, j) where i and j are products of (a, b) and (c, d) respectively
    for i in range(1, a + 1):
        for j in range(1, b + 1):
            for k in range(1, c + 1):
                for l in range(1, d + 1):
                    if i * j == a * b and k * l == c * d:
                        pairs.add((i, j))
                        pairs.add((k, l))

    # Initialize a set to keep track of valid pairs
    valid_pairs = set()

