def bird_code(arr):
    def create_code(name):
        # Split the name by spaces and hyphens
        words = name.replace('-', ' ').split()
        num_words = len(words)

        if num_words == 1:
            # If the name has only one word, take the first four letters
            return words[0][:4].upper()
        elif num_words == 2:
            # If the name has two words, take the first two letters of each word
            return words[0][:2].upper() + words[1][:2].upper()
        elif num_words == 3:
            # If the name has three words, take the first letter from the first two words and the first two letters from the third word
            return words[0][:1] + words[1][:1] + words[2][:2].upper()
