def findCodwars(url):
    # Use regular expression to extract the domain part of the URL
    match = re.match(r'https?://([^/?]+)', url)
    if not match:
        return False

    domain = match.group(1)

    # Check if the domain matches "codwars.com" or "subdomain.codwars.com"
    return domain == "codwars.com" or domain.endswith(".codwars.com")

import re

def findCodwars(url):
    # Regular expression to match codwars.com or subdomains containing codwars.com
    pattern = r"^(?:https?:\/\/)?(?:subdomain\.)?codwars\.com"

    # Use re.match to check if the URL matches the pattern
    return bool(re.match(pattern, url))

